// CLI argument parsing - clap-compatible behavior

use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct ParsedArgs {
    pub pattern: Option<String>,
    pub paths: Vec<String>,
    pub editor: Option<String>,
    pub custom_command: Option<String>,
    pub theme: Option<String>,
    pub ignore_case: bool,
    pub smart_case: bool,
    pub hidden: bool,
    pub follow: bool,
    pub word_regexp: bool,
    pub fixed_strings: bool,
    pub multiline: bool,
    pub globs: Vec<String>,
    pub types: Vec<String>,
    pub types_not: Vec<String>,
    pub type_list: bool,
    pub context_viewer: Option<String>,
    pub sort: Option<String>,
    pub sortr: Option<String>,
    // order in which flags were provided (for error usage line)
    pub flag_order: Vec<&'static str>,
}

impl ParsedArgs {
    fn new() -> Self {
        Self {
            pattern: None,
            paths: Vec::new(),
            editor: None,
            custom_command: None,
            theme: None,
            ignore_case: false,
            smart_case: false,
            hidden: false,
            follow: false,
            word_regexp: false,
            fixed_strings: false,
            multiline: false,
            globs: Vec::new(),
            types: Vec::new(),
            types_not: Vec::new(),
            type_list: false,
            context_viewer: None,
            sort: None,
            sortr: None,
            flag_order: Vec::new(),
        }
    }
}

pub enum ParseAction {
    Run(ParsedArgs),
    PrintHelp,
    PrintVersion,
}

pub enum ParseError {
    UnexpectedArgument {
        arg: String,
        similar: Option<&'static str>,
        flag_order: Vec<&'static str>,
    },
    MissingValue {
        name: &'static str,       // e.g. "glob"
        display: &'static str,    // e.g. "--glob <GLOB>"
        possible: Option<&'static str>,
    },
    InvalidValue {
        display: &'static str,    // e.g. "--editor <EDITOR>"
        value: String,
        possible: &'static str,
    },
    DuplicateFlag {
        display: &'static str,    // e.g. "--editor <EDITOR>" or "--fixed-strings"
    },
    ConflictWith {
        first: String,  // e.g. "'--editor <EDITOR>'"
        second: String, // e.g. "'--custom-command <CUSTOM_COMMAND>'"
        flag_order: Vec<&'static str>,
    },
    MissingRequired {
        flag_order: Vec<&'static str>,
    },
}

pub const EDITOR_VALUES: &[&str] = &[
    "vim", "neovim", "nvim", "nano", "code", "vscode", "code-insiders",
    "emacs", "emacsclient", "hx", "helix", "subl", "sublime-text", "micro",
    "intellij", "goland", "pycharm", "less", "fresh",
];

pub const THEME_VALUES: &[&str] = &["light", "dark"];
pub const CONTEXT_VIEWER_VALUES: &[&str] = &["none", "vertical", "horizontal"];
pub const SORT_VALUES: &[&str] = &["path", "modified", "created", "accessed"];

pub const EDITOR_POSSIBLE: &str = "vim, neovim, nvim, nano, code, vscode, code-insiders, emacs, emacsclient, hx, helix, subl, sublime-text, micro, intellij, goland, pycharm, less, fresh";
pub const THEME_POSSIBLE: &str = "light, dark";
pub const CONTEXT_VIEWER_POSSIBLE: &str = "none, vertical, horizontal";
pub const SORT_POSSIBLE: &str = "path, modified, created, accessed";

// Map from flag name (internal) to display form used in usage line
pub fn flag_usage(name: &str) -> &'static str {
    match name {
        "editor" => "--editor <EDITOR>",
        "custom-command" => "--custom-command <CUSTOM_COMMAND>",
        "theme" => "--theme <THEME>",
        "ignore-case" => "--ignore-case",
        "smart-case" => "--smart-case",
        "hidden" => "--hidden",
        "follow" => "--follow",
        "word-regexp" => "--word-regexp",
        "fixed-strings" => "--fixed-strings",
        "multiline" => "--multiline",
        "glob" => "--glob <GLOB>",
        "type" => "--type <TYPE_MATCHING>",
        "type-not" => "--type-not <TYPE_NOT>",
        "context-viewer" => "--context-viewer <CONTEXT_VIEWER>",
        "sort" => "--sort <SORT_BY>",
        "sortr" => "--sortr <SORT_BY_REVERSE>",
        "type-list" => "--type-list",
        "help" => "--help",
        "version" => "--version",
        _ => "",
    }
}

fn known_long_flags() -> Vec<&'static str> {
    vec![
        "--editor", "--custom-command", "--theme", "--ignore-case", "--smart-case",
        "--hidden", "--follow", "--word-regexp", "--fixed-strings", "--multiline",
        "--glob", "--type-list", "--type", "--type-not", "--context-viewer",
        "--sort", "--sortr", "--help", "--version",
    ]
}

fn find_similar(arg: &str) -> Option<&'static str> {
    let candidates = known_long_flags();
    let mut best: Option<(&'static str, usize)> = None;
    for c in candidates {
        let d = edit_distance(arg, c);
        if d <= 3 {
            match best {
                None => best = Some((c, d)),
                Some((_, bd)) if d < bd => best = Some((c, d)),
                _ => {}
            }
        }
    }
    best.map(|(s, _)| s)
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let n = a.len();
    let m = b.len();
    if n == 0 { return m; }
    if m == 0 { return n; }
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut curr = vec![0usize; m + 1];
    for i in 1..=n {
        curr[0] = i;
        for j in 1..=m {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            curr[j] = std::cmp::min(
                std::cmp::min(prev[j] + 1, curr[j - 1] + 1),
                prev[j - 1] + cost,
            );
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[m]
}

pub fn parse_args(argv: &[String]) -> Result<ParseAction, ParseError> {
    let mut parsed = ParsedArgs::new();
    let mut seen: HashMap<&'static str, bool> = HashMap::new();

    let mut i = 0;
    let mut positional_only = false;

    fn mark_seen(
        seen: &mut HashMap<&'static str, bool>,
        order: &mut Vec<&'static str>,
        name: &'static str,
    ) {
        if !seen.contains_key(name) {
            order.push(name);
        }
        seen.insert(name, true);
    }

    while i < argv.len() {
        let a = &argv[i];
        if positional_only {
            if parsed.pattern.is_none() {
                parsed.pattern = Some(a.clone());
            } else {
                parsed.paths.push(a.clone());
            }
            i += 1;
            continue;
        }

        if a == "--" {
            positional_only = true;
            i += 1;
            continue;
        }

        // Long option: --name or --name=value
        if a.starts_with("--") {
            let (name, inline_value) = match a.find('=') {
                Some(p) => (a[..p].to_string(), Some(a[p + 1..].to_string())),
                None => (a.clone(), None),
            };

            match name.as_str() {
                "--help" => return Ok(ParseAction::PrintHelp),
                "--version" => return Ok(ParseAction::PrintVersion),
                "--type-list" => {
                    if parsed.type_list {
                        return Err(ParseError::DuplicateFlag { display: "--type-list" });
                    }
                    parsed.type_list = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "type-list");
                }
                "--ignore-case" => {
                    if parsed.ignore_case {
                        return Err(ParseError::DuplicateFlag { display: "--ignore-case" });
                    }
                    parsed.ignore_case = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "ignore-case");
                }
                "--smart-case" => {
                    if parsed.smart_case {
                        return Err(ParseError::DuplicateFlag { display: "--smart-case" });
                    }
                    parsed.smart_case = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "smart-case");
                }
                "--hidden" => {
                    if parsed.hidden {
                        return Err(ParseError::DuplicateFlag { display: "--hidden" });
                    }
                    parsed.hidden = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "hidden");
                }
                "--follow" => {
                    if parsed.follow {
                        return Err(ParseError::DuplicateFlag { display: "--follow" });
                    }
                    parsed.follow = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "follow");
                }
                "--word-regexp" => {
                    if parsed.word_regexp {
                        return Err(ParseError::DuplicateFlag { display: "--word-regexp" });
                    }
                    parsed.word_regexp = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "word-regexp");
                }
                "--fixed-strings" => {
                    if parsed.fixed_strings {
                        return Err(ParseError::DuplicateFlag { display: "--fixed-strings" });
                    }
                    parsed.fixed_strings = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "fixed-strings");
                }
                "--multiline" => {
                    if parsed.multiline {
                        return Err(ParseError::DuplicateFlag { display: "--multiline" });
                    }
                    parsed.multiline = true;
                    mark_seen(&mut seen, &mut parsed.flag_order, "multiline");
                }
                "--editor" => {
                    if parsed.editor.is_some() {
                        return Err(ParseError::DuplicateFlag { display: "--editor <EDITOR>" });
                    }
                    let v = get_value(&name, inline_value, argv, &mut i, "editor", "--editor <EDITOR>", Some(EDITOR_POSSIBLE))?;
                    if !EDITOR_VALUES.contains(&v.as_str()) {
                        return Err(ParseError::InvalidValue {
                            display: "--editor <EDITOR>",
                            value: v,
                            possible: EDITOR_POSSIBLE,
                        });
                    }
                    parsed.editor = Some(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "editor");
                }
                "--custom-command" => {
                    if parsed.custom_command.is_some() {
                        return Err(ParseError::DuplicateFlag { display: "--custom-command <CUSTOM_COMMAND>" });
                    }
                    let v = get_value(&name, inline_value, argv, &mut i, "custom-command", "--custom-command <CUSTOM_COMMAND>", None)?;
                    parsed.custom_command = Some(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "custom-command");
                }
                "--theme" => {
                    if parsed.theme.is_some() {
                        return Err(ParseError::DuplicateFlag { display: "--theme <THEME>" });
                    }
                    let v = get_value(&name, inline_value, argv, &mut i, "theme", "--theme <THEME>", Some(THEME_POSSIBLE))?;
                    if !THEME_VALUES.contains(&v.as_str()) {
                        return Err(ParseError::InvalidValue {
                            display: "--theme <THEME>",
                            value: v,
                            possible: THEME_POSSIBLE,
                        });
                    }
                    parsed.theme = Some(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "theme");
                }
                "--context-viewer" => {
                    if parsed.context_viewer.is_some() {
                        return Err(ParseError::DuplicateFlag { display: "--context-viewer <CONTEXT_VIEWER>" });
                    }
                    let v = get_value(&name, inline_value, argv, &mut i, "context-viewer", "--context-viewer <CONTEXT_VIEWER>", Some(CONTEXT_VIEWER_POSSIBLE))?;
                    if !CONTEXT_VIEWER_VALUES.contains(&v.as_str()) {
                        return Err(ParseError::InvalidValue {
                            display: "--context-viewer <CONTEXT_VIEWER>",
                            value: v,
                            possible: CONTEXT_VIEWER_POSSIBLE,
                        });
                    }
                    parsed.context_viewer = Some(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "context-viewer");
                }
                "--sort" => {
                    if parsed.sort.is_some() {
                        return Err(ParseError::DuplicateFlag { display: "--sort <SORT_BY>" });
                    }
                    let v = get_value(&name, inline_value, argv, &mut i, "sort", "--sort <SORT_BY>", Some(SORT_POSSIBLE))?;
                    if !SORT_VALUES.contains(&v.as_str()) {
                        return Err(ParseError::InvalidValue {
                            display: "--sort <SORT_BY>",
                            value: v,
                            possible: SORT_POSSIBLE,
                        });
                    }
                    parsed.sort = Some(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "sort");
                }
                "--sortr" => {
                    if parsed.sortr.is_some() {
                        return Err(ParseError::DuplicateFlag { display: "--sortr <SORT_BY_REVERSE>" });
                    }
                    let v = get_value(&name, inline_value, argv, &mut i, "sortr", "--sortr <SORT_BY_REVERSE>", Some(SORT_POSSIBLE))?;
                    if !SORT_VALUES.contains(&v.as_str()) {
                        return Err(ParseError::InvalidValue {
                            display: "--sortr <SORT_BY_REVERSE>",
                            value: v,
                            possible: SORT_POSSIBLE,
                        });
                    }
                    parsed.sortr = Some(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "sortr");
                }
                "--glob" => {
                    let v = get_value(&name, inline_value, argv, &mut i, "glob", "--glob <GLOB>", None)?;
                    parsed.globs.push(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "glob");
                }
                "--type" => {
                    let v = get_value(&name, inline_value, argv, &mut i, "type", "--type <TYPE_MATCHING>", None)?;
                    parsed.types.push(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "type");
                }
                "--type-not" => {
                    let v = get_value(&name, inline_value, argv, &mut i, "type-not", "--type-not <TYPE_NOT>", None)?;
                    parsed.types_not.push(v);
                    mark_seen(&mut seen, &mut parsed.flag_order, "type-not");
                }
                _ => {
                    return Err(ParseError::UnexpectedArgument {
                        arg: name.clone(),
                        similar: find_similar(&name),
                        flag_order: parsed.flag_order.clone(),
                    });
                }
            }
            i += 1;
            continue;
        }

        // Short option: -x or -xvalue or combined -abc
        if a.starts_with('-') && a.len() > 1 && a != "-" {
            // parse short opts
            let bytes: Vec<char> = a[1..].chars().collect();
            let mut j = 0;
            while j < bytes.len() {
                let c = bytes[j];
                match c {
                    'h' => return Ok(ParseAction::PrintHelp),
                    'V' => return Ok(ParseAction::PrintVersion),
                    'i' => {
                        if parsed.ignore_case {
                            return Err(ParseError::DuplicateFlag { display: "--ignore-case" });
                        }
                        parsed.ignore_case = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "ignore-case");
                    }
                    'S' => {
                        if parsed.smart_case {
                            return Err(ParseError::DuplicateFlag { display: "--smart-case" });
                        }
                        parsed.smart_case = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "smart-case");
                    }
                    '.' => {
                        if parsed.hidden {
                            return Err(ParseError::DuplicateFlag { display: "--hidden" });
                        }
                        parsed.hidden = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "hidden");
                    }
                    'L' => {
                        if parsed.follow {
                            return Err(ParseError::DuplicateFlag { display: "--follow" });
                        }
                        parsed.follow = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "follow");
                    }
                    'w' => {
                        if parsed.word_regexp {
                            return Err(ParseError::DuplicateFlag { display: "--word-regexp" });
                        }
                        parsed.word_regexp = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "word-regexp");
                    }
                    'F' => {
                        if parsed.fixed_strings {
                            return Err(ParseError::DuplicateFlag { display: "--fixed-strings" });
                        }
                        parsed.fixed_strings = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "fixed-strings");
                    }
                    'U' => {
                        if parsed.multiline {
                            return Err(ParseError::DuplicateFlag { display: "--multiline" });
                        }
                        parsed.multiline = true;
                        mark_seen(&mut seen, &mut parsed.flag_order, "multiline");
                    }
                    'g' | 't' | 'T' => {
                        // value expected
                        let (name, display) = match c {
                            'g' => ("glob", "--glob <GLOB>"),
                            't' => ("type", "--type <TYPE_MATCHING>"),
                            'T' => ("type-not", "--type-not <TYPE_NOT>"),
                            _ => unreachable!(),
                        };
                        // remaining in same arg?
                        let rest: String = bytes[j + 1..].iter().collect();
                        let v = if !rest.is_empty() {
                            j = bytes.len(); // consume rest
                            rest
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return Err(ParseError::MissingValue {
                                    name,
                                    display,
                                    possible: None,
                                });
                            }
                            argv[i].clone()
                        };
                        match c {
                            'g' => parsed.globs.push(v),
                            't' => parsed.types.push(v),
                            'T' => parsed.types_not.push(v),
                            _ => {}
                        }
                        mark_seen(&mut seen, &mut parsed.flag_order, name);
                    }
                    _ => {
                        return Err(ParseError::UnexpectedArgument {
                            arg: format!("-{}", c),
                            similar: None,
                            flag_order: parsed.flag_order.clone(),
                        });
                    }
                }
                j += 1;
            }
            i += 1;
            continue;
        }

        // Positional argument
        if parsed.pattern.is_none() {
            parsed.pattern = Some(a.clone());
        } else {
            parsed.paths.push(a.clone());
        }
        i += 1;
    }

    // Post-parse validation

    // --type-list conflicts with <PATTERN>
    if parsed.type_list && parsed.pattern.is_some() {
        // Which comes "second"? The one that appears later in the argv
        // For simplicity, if pattern is set and --type-list is seen, which comes last?
        // The parsing stops at the first, so we need to check the order of args in argv.
        let (first, second) = determine_conflict_order(argv, "--type-list", None);
        return Err(ParseError::ConflictWith {
            first: second,
            second: first,
            flag_order: Vec::new(), // Uses basic usage
        });
    }

    // --editor conflicts with --custom-command
    if parsed.editor.is_some() && parsed.custom_command.is_some() {
        let (first, second) = determine_conflict_order(argv, "--editor", Some("--custom-command"));
        return Err(ParseError::ConflictWith {
            first: second,
            second: first,
            flag_order: flag_order_for_one(&parsed.flag_order, &second_of(&second)),
        });
    }

    if !parsed.type_list && parsed.pattern.is_none() {
        // Missing required args
        return Err(ParseError::MissingRequired {
            flag_order: parsed.flag_order.clone(),
        });
    }

    Ok(ParseAction::Run(parsed))
}

// Given the second-conflicting flag string, extract which flag that is
fn second_of(display: &str) -> &'static str {
    if display.contains("--editor") { "editor" }
    else if display.contains("--custom-command") { "custom-command" }
    else if display.contains("--type-list") { "type-list" }
    else { "" }
}

fn flag_order_for_one(order: &[&'static str], name: &str) -> Vec<&'static str> {
    // Return only the given flag (and type-list if present)
    let mut result = Vec::new();
    if order.contains(&"type-list") { result.push("type-list"); }
    for &f in order {
        if f == name && !result.contains(&f) {
            result.push(f);
        }
    }
    result
}

fn determine_conflict_order(argv: &[String], a: &str, b: Option<&str>) -> (String, String) {
    // Return ("first specified", "second specified")
    // If only `a` is specified and b is None, positional is the other.
    let mut positions: Vec<(usize, String)> = Vec::new();
    for (i, x) in argv.iter().enumerate() {
        if x == a || x.starts_with(&format!("{}=", a)) {
            positions.push((i, flag_display(a).to_string()));
        }
        if let Some(bb) = b {
            if x == bb || x.starts_with(&format!("{}=", bb)) {
                positions.push((i, flag_display(bb).to_string()));
            }
        }
    }
    if b.is_none() {
        // Find first non-option positional (pattern)
        // Treat the pattern as <PATTERN>
        let mut positional_only = false;
        for (i, x) in argv.iter().enumerate() {
            if !positional_only && x == "--" { positional_only = true; continue; }
            if positional_only || (!x.starts_with('-') || x == "-") {
                positions.push((i, "<PATTERN>".to_string()));
                break;
            }
        }
    }
    positions.sort_by_key(|&(i, _)| i);
    if positions.len() >= 2 {
        let first = positions[0].1.clone();
        let second = positions[positions.len() - 1].1.clone();
        (first, second)
    } else {
        (String::new(), String::new())
    }
}

fn flag_display(flag: &str) -> &'static str {
    match flag {
        "--editor" => "--editor <EDITOR>",
        "--custom-command" => "--custom-command <CUSTOM_COMMAND>",
        "--theme" => "--theme <THEME>",
        "--context-viewer" => "--context-viewer <CONTEXT_VIEWER>",
        "--sort" => "--sort <SORT_BY>",
        "--sortr" => "--sortr <SORT_BY_REVERSE>",
        "--glob" => "--glob <GLOB>",
        "--type" => "--type <TYPE_MATCHING>",
        "--type-not" => "--type-not <TYPE_NOT>",
        "--type-list" => "--type-list",
        _ => "",
    }
}

fn get_value(
    name: &str,
    inline: Option<String>,
    argv: &[String],
    i: &mut usize,
    _flag_name: &'static str,
    display: &'static str,
    possible: Option<&'static str>,
) -> Result<String, ParseError> {
    if let Some(v) = inline { return Ok(v); }
    *i += 1;
    if *i >= argv.len() {
        return Err(ParseError::MissingValue {
            name: _flag_name,
            display,
            possible,
        });
    }
    let _ = name;
    Ok(argv[*i].clone())
}
