  -t, --type <TYPE_MATCHING>
          Only search files matching TYPE. Multiple types may be provided
  -T, --type-not <TYPE_NOT>
          Do not search files matching TYPE-NOT. Multiple types-not may be provided
      --context-viewer <CONTEXT_VIEWER>
          Context viewer position at startup [default: none] [possible values: none, vertical, horizontal]
      --sort <SORT_BY>
          Sort results, see ripgrep for details [possible values: path, modified, created, accessed]
      --sortr <SORT_BY_REVERSE>
          Sort results reverse, see ripgrep for details [possible values: path, modified, created, accessed]
  -h, --help
          Print help
  -V, --version
          Print version
", prog = prog);
    print!("{}", help);
}

fn print_version() {
    println!("igrep {}", VERSION);
}

fn print_type_list() {
    print!("{}", types::TYPELIST);
}

/// Build the "Usage: ..." line based on currently-provided flags.
/// `flags` is a list of flag identifiers in argv order (no duplicates).
fn usage_line(prog: &str, flags: &[&str]) -> String {
    if flags.is_empty() {
        format!("Usage: {} [OPTIONS] --type-list <PATTERN> [PATHS]...", prog)
    } else {
        let mut s = format!("Usage: {} --type-list", prog);
        for f in flags {
            if *f == "type-list" { continue; }
            s.push(' ');
            s.push_str(flag_usage_str(f));
        }
        s.push_str(" <PATTERN> [PATHS]...");
        s
    }
}

fn flag_usage_str(f: &str) -> &'static str {
    match f {
        "editor" => "--editor <EDITOR>",
        "custom-command" => "--custom-command <CUSTOM_COMMAND>",
        "theme" => "--theme <THEME>",
        "ignore-case" => "--ignore-case",
        "smart-case" => "--smart-case",
        "hidden" => "--hidden",
        "follow" => "--follow",
        "word-regexp" => "--word-regexp",
        "fixed-strings" => "--fixed-strings",
        "multiline" => "--multiline",
        "glob" => "--glob <GLOB>",
        "type" => "--type <TYPE_MATCHING>",
        "type-not" => "--type-not <TYPE_NOT>",
        "context-viewer" => "--context-viewer <CONTEXT_VIEWER>",
        "sort" => "--sort <SORT_BY>",
        "sortr" => "--sortr <SORT_BY_REVERSE>",
        "type-list" => "--type-list",
        "help" => "--help",
        "version" => "--version",
        _ => "",
    }
}

fn print_clap_error(prog: &str, msg: &str, show_tip: Option<&str>, flags: &[&str]) {
    let mut out = String::new();
    out.push_str("error: ");
    out.push_str(msg);
    out.push('\n');
    if let Some(tip) = show_tip {
        out.push('\n');
        out.push_str("  tip: ");
        out.push_str(tip);
        out.push('\n');
    }
    out.push('\n');
    out.push_str(&usage_line(prog, flags));
    out.push_str("\n\nFor more information, try '--help'.\n");
    eprint!("{}", out);
}

// Edit distance for "similar argument" suggestions
fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let n = a.len();
    let m = b.len();
    if n == 0 { return m; }
    if m == 0 { return n; }
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut curr = vec![0usize; m + 1];
    for i in 1..=n {
        curr[0] = i;
        for j in 1..=m {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            curr[j] = std::cmp::min(
                std::cmp::min(prev[j] + 1, curr[j - 1] + 1),
                prev[j - 1] + cost,
            );
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[m]
}

fn find_similar(arg: &str) -> Option<&'static str> {
    let mut best: Option<(&'static str, usize)> = None;
    for c in KNOWN_LONG {
        let d = edit_distance(arg, c);
        if d <= 3 {
            match best {
                None => best = Some((*c, d)),
                Some((_, bd)) if d < bd => best = Some((*c, d)),
                _ => {}
            }
        }
    }
    best.map(|(s, _)| s)
}

#[derive(Default)]
struct Parsed {
    pattern: Option<String>,
    paths: Vec<String>,
    editor: Option<String>,
    custom_command: Option<String>,
    theme: Option<String>,
    ignore_case: bool,
    smart_case: bool,
    hidden: bool,
    follow: bool,
    word_regexp: bool,
    fixed_strings: bool,
    multiline: bool,
    globs: Vec<String>,
    types_: Vec<String>,
    types_not: Vec<String>,
    type_list: bool,
    context_viewer: Option<String>,
    sort: Option<String>,
    sortr: Option<String>,
    // Argv-order sequence of flags seen (unique, order preserved)
    flag_seq: Vec<&'static str>,
    // Track index of first appearance of various things in argv for conflict reporting
    idx_pattern: Option<usize>,
    idx_type_list: Option<usize>,
    idx_editor: Option<usize>,
    idx_custom_command: Option<usize>,
}

impl Parsed {
    fn push_flag(&mut self, name: &'static str) {
        if !self.flag_seq.contains(&name) {
            self.flag_seq.push(name);
        }
    }
}

enum Action {
    Help,
    Version,
    TypeList(Parsed),
    Run(Parsed),
}

fn parse_args(argv: &[String], prog: &str) -> Result<Action, i32> {
    let mut p = Parsed::default();
    let mut positional_only = false;
    let mut i = 0;

    // Handle `--` semantics; we want original index preserved for idx tracking

    while i < argv.len() {
        let arg = argv[i].clone();

        if positional_only {
            if p.pattern.is_none() {
                p.pattern = Some(arg);
                p.idx_pattern = Some(i);
            } else {
                p.paths.push(arg);
            }
            i += 1;
            continue;
        }

        if arg == "--" {
            positional_only = true;
            i += 1;
            continue;
        }

        if arg == "--help" || arg == "-h" {
            return Ok(Action::Help);
        }
        if arg == "--version" || arg == "-V" {
            return Ok(Action::Version);
        }

        // Long options
        if arg.starts_with("--") {
            let (name, inline) = if let Some(eq) = arg.find('=') {
                (arg[..eq].to_string(), Some(arg[eq + 1..].to_string()))
            } else {
                (arg.clone(), None)
            };
            match name.as_str() {
                "--type-list" => {
                    if p.type_list {
                        print_clap_error(prog, "the argument '--type-list' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.type_list = true;
                    p.push_flag("type-list");
                    p.idx_type_list = Some(i);
                    i += 1;
                }
                "--ignore-case" => {
                    if p.ignore_case {
                        print_clap_error(prog, "the argument '--ignore-case' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.ignore_case = true;
                    p.push_flag("ignore-case");
                    i += 1;
                }
                "--smart-case" => {
                    if p.smart_case {
                        print_clap_error(prog, "the argument '--smart-case' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.smart_case = true;
                    p.push_flag("smart-case");
                    i += 1;
                }
                "--hidden" => {
                    if p.hidden {
                        print_clap_error(prog, "the argument '--hidden' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.hidden = true;
                    p.push_flag("hidden");
                    i += 1;
                }
                "--follow" => {
                    if p.follow {
                        print_clap_error(prog, "the argument '--follow' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.follow = true;
                    p.push_flag("follow");
                    i += 1;
                }
                "--word-regexp" => {
                    if p.word_regexp {
                        print_clap_error(prog, "the argument '--word-regexp' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.word_regexp = true;
                    p.push_flag("word-regexp");
                    i += 1;
                }
                "--fixed-strings" => {
                    if p.fixed_strings {
                        print_clap_error(prog, "the argument '--fixed-strings' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.fixed_strings = true;
                    p.push_flag("fixed-strings");
                    i += 1;
                }
                "--multiline" => {
                    if p.multiline {
                        print_clap_error(prog, "the argument '--multiline' cannot be used multiple times", None, &[]);
                        return Err(2);
                    }
                    p.multiline = true;
                    p.push_flag("multiline");
                    i += 1;
                }
                "--editor" | "--custom-command" | "--theme" | "--context-viewer"
                | "--sort" | "--sortr" | "--glob" | "--type" | "--type-not" => {
                    // value required
                    let v = match inline {
                        Some(v) => { i += 1; v }
                        None => {
                            if i + 1 >= argv.len() {
                                missing_value_error(prog, &name);
                                return Err(2);
                            }
                            let v = argv[i + 1].clone();
                            i += 2;
                            v
                        }
                    };
                    match name.as_str() {
                        "--editor" => {
                            if p.editor.is_some() {
                                print_clap_error(prog, "the argument '--editor <EDITOR>' cannot be used multiple times", None, &[]);
                                return Err(2);
                            }
                            if !EDITOR_VALUES.contains(&v.as_str()) {
                                let msg = format!(
                                    "invalid value '{}' for '--editor <EDITOR>'\n  [possible values: {}]",
                                    v, EDITOR_POSSIBLE
                                );
                                print_clap_error_noflag(prog, &msg);
                                return Err(2);
                            }
                            p.editor = Some(v);
                            p.push_flag("editor");
                            p.idx_editor = Some(i - 2);
                        }
                        "--custom-command" => {
                            if p.custom_command.is_some() {
                                print_clap_error(prog, "the argument '--custom-command <CUSTOM_COMMAND>' cannot be used multiple times", None, &[]);
                                return Err(2);
                            }
                            p.custom_command = Some(v);
                            p.push_flag("custom-command");
                            p.idx_custom_command = Some(i - 2);
                        }
                        "--theme" => {
                            if p.theme.is_some() {
                                print_clap_error(prog, "the argument '--theme <THEME>' cannot be used multiple times", None, &[]);
                                return Err(2);
                            }
                            if !THEME_VALUES.contains(&v.as_str()) {
                                let msg = format!(
                                    "invalid value '{}' for '--theme <THEME>'\n  [possible values: {}]",
                                    v, THEME_POSSIBLE
                                );
                                print_clap_error_noflag(prog, &msg);
                                return Err(2);
                            }
                            p.theme = Some(v);
                            p.push_flag("theme");
                        }
                        "--context-viewer" => {
                            if p.context_viewer.is_some() {
                                print_clap_error(prog, "the argument '--context-viewer <CONTEXT_VIEWER>' cannot be used multiple times", None, &[]);
                                return Err(2);
                            }
                            if !CONTEXT_VIEWER_VALUES.contains(&v.as_str()) {
                                let msg = format!(
                                    "invalid value '{}' for '--context-viewer <CONTEXT_VIEWER>'\n  [possible values: {}]",
                                    v, CONTEXT_VIEWER_POSSIBLE
                                );
                                print_clap_error_noflag(prog, &msg);
                                return Err(2);
                            }
                            p.context_viewer = Some(v);
                            p.push_flag("context-viewer");
                        }
                        "--sort" => {
                            if p.sort.is_some() {
                                print_clap_error(prog, "the argument '--sort <SORT_BY>' cannot be used multiple times", None, &[]);
                                return Err(2);
                            }
                            if !SORT_VALUES.contains(&v.as_str()) {
                                let msg = format!(
                                    "invalid value '{}' for '--sort <SORT_BY>'\n  [possible values: {}]",
                                    v, SORT_POSSIBLE
                                );
                                print_clap_error_noflag(prog, &msg);
                                return Err(2);
                            }
                            p.sort = Some(v);
                            p.push_flag("sort");
                        }
                        "--sortr" => {
                            if p.sortr.is_some() {
                                print_clap_error(prog, "the argument '--sortr <SORT_BY_REVERSE>' cannot be used multiple times", None, &[]);
                                return Err(2);
                            }
                            if !SORT_VALUES.contains(&v.as_str()) {
                                let msg = format!(
                                    "invalid value '{}' for '--sortr <SORT_BY_REVERSE>'\n  [possible values: {}]",
                                    v, SORT_POSSIBLE
                                );
                                print_clap_error_noflag(prog, &msg);
                                return Err(2);
                            }
                            p.sortr = Some(v);
                            p.push_flag("sortr");
                        }
                        "--glob" => {
                            p.globs.push(v);
                            p.push_flag("glob");
                        }
                        "--type" => {
                            p.types_.push(v);
                            p.push_flag("type");
                        }
                        "--type-not" => {
                            p.types_not.push(v);
                            p.push_flag("type-not");
                        }
                        _ => unreachable!(),
                    }
                }
                _ => {
                    // Unknown argument
                    let similar = find_similar(&name);
                    let tip = match similar {
                        Some(s) => format!("a similar argument exists: '{}'", s),
                        None => format!("to pass '{}' as a value, use '-- {}'", name, name),
                    };
                    let msg = format!("unexpected argument '{}' found", name);
                    let mut flags_for_usage: Vec<&str> = p.flag_seq.clone();
                    if let Some(s) = similar {
                        // clap includes the "similar" arg in usage line as well as existing flags
                        let fn_name: &'static str = match s {
                            "--editor" => "editor",
                            "--custom-command" => "custom-command",
                            "--theme" => "theme",
                            "--ignore-case" => "ignore-case",
                            "--smart-case" => "smart-case",
                            "--hidden" => "hidden",
                            "--follow" => "follow",
                            "--word-regexp" => "word-regexp",
                            "--fixed-strings" => "fixed-strings",
                            "--multiline" => "multiline",
                            "--glob" => "glob",
                            "--type-list" => "type-list",
                            "--type" => "type",
                            "--type-not" => "type-not",
                            "--context-viewer" => "context-viewer",
                            "--sort" => "sort",
                            "--sortr" => "sortr",
                            "--help" => "help",
                            "--version" => "version",
                            _ => "",
                        };
                        if !fn_name.is_empty() && !flags_for_usage.contains(&fn_name) {
                            flags_for_usage.push(fn_name);
                        }
                    }
                    print_clap_error(prog, &msg, Some(&tip), &flags_for_usage);
                    return Err(2);
                }
            }
            continue;
        }

        // Short options
        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'h' => return Ok(Action::Help),
                    'V' => return Ok(Action::Version),
                    'i' => {
                        if p.ignore_case {
                            print_clap_error(prog, "the argument '--ignore-case' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.ignore_case = true;
                        p.push_flag("ignore-case");
                    }
                    'S' => {
                        if p.smart_case {
                            print_clap_error(prog, "the argument '--smart-case' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.smart_case = true;
                        p.push_flag("smart-case");
                    }
                    '.' => {
                        if p.hidden {
                            print_clap_error(prog, "the argument '--hidden' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.hidden = true;
                        p.push_flag("hidden");
                    }
                    'L' => {
                        if p.follow {
                            print_clap_error(prog, "the argument '--follow' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.follow = true;
                        p.push_flag("follow");
                    }
                    'w' => {
                        if p.word_regexp {
                            print_clap_error(prog, "the argument '--word-regexp' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.word_regexp = true;
                        p.push_flag("word-regexp");
                    }
                    'F' => {
                        if p.fixed_strings {
                            print_clap_error(prog, "the argument '--fixed-strings' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.fixed_strings = true;
                        p.push_flag("fixed-strings");
                    }
                    'U' => {
                        if p.multiline {
                            print_clap_error(prog, "the argument '--multiline' cannot be used multiple times", None, &[]);
                            return Err(2);
                        }
                        p.multiline = true;
                        p.push_flag("multiline");
                    }
                    'g' | 't' | 'T' => {
                        let (name_str, display_str, flag_id) = match c {
                            'g' => ("--glob", "--glob <GLOB>", "glob"),
                            't' => ("--type", "--type <TYPE_MATCHING>", "type"),
                            'T' => ("--type-not", "--type-not <TYPE_NOT>", "type-not"),
                            _ => unreachable!(),
                        };
                        let rest: String = chars[j + 1..].iter().collect();
                        let v = if !rest.is_empty() {
                            j = chars.len(); // consume rest
                            rest
                        } else {
                            if i + 1 >= argv.len() {
                                missing_value_error(prog, name_str);
                                return Err(2);
                            }
                            i += 1;
                            argv[i].clone()
                        };
                        let _ = display_str;
                        match c {
                            'g' => p.globs.push(v),
                            't' => p.types_.push(v),
                            'T' => p.types_not.push(v),
                            _ => {}
                        }
                        p.push_flag(flag_id);
                    }
                    _ => {
                        let arg_str = format!("-{}", c);
                        let tip = format!("to pass '{}' as a value, use '-- {}'", arg_str, arg_str);
                        let msg = format!("unexpected argument '{}' found", arg_str);
                        print_clap_error(prog, &msg, Some(&tip), &p.flag_seq);
                        return Err(2);
                    }
                }
                j += 1;
            }
            i += 1;
            continue;
        }

        // Positional
        if p.pattern.is_none() {
            p.pattern = Some(arg);
            p.idx_pattern = Some(i);
        } else {
            p.paths.push(arg);
        }
        i += 1;
    }

    // Post-parse validation

    // Check conflict --editor vs --custom-command
    if let (Some(ie), Some(ic)) = (p.idx_editor, p.idx_custom_command) {
        // The one that was specified FIRST (lower index) is X, other is Y.
        // Usage shows X.
        let (x_disp, y_disp, x_flag) = if ie < ic {
            ("--editor <EDITOR>", "--custom-command <CUSTOM_COMMAND>", "editor")
        } else {
            ("--custom-command <CUSTOM_COMMAND>", "--editor <EDITOR>", "custom-command")
        };
        let msg = format!("the argument '{}' cannot be used with '{}'", x_disp, y_disp);
        let mut flags_for_usage: Vec<&str> = Vec::new();
        if p.type_list { flags_for_usage.push("type-list"); }
        flags_for_usage.push(x_flag);
        print_clap_error_fixed_usage(prog, &msg, &flags_for_usage);
        return Err(2);
    }

    // Check --type-list conflicts with <PATTERN>
    if p.type_list && p.pattern.is_some() {
        let it = p.idx_type_list.unwrap_or(usize::MAX);
        let ip = p.idx_pattern.unwrap_or(usize::MAX);
        let (x, y) = if it < ip {
            ("'--type-list'", "'<PATTERN>'")
        } else {
            ("'<PATTERN>'", "'--type-list'")
        };
        let msg = format!("the argument {} cannot be used with {}", x, y);
        // Usage line: always "executable --type-list <PATTERN> [PATHS]..."
        let out = format!(
            "error: {}\n\nUsage: {} --type-list <PATTERN> [PATHS]...\n\nFor more information, try '--help'.\n",
            msg, prog
        );
        eprint!("{}", out);
        return Err(2);
    }

    // Missing required
    if !p.type_list && p.pattern.is_none() {
        let header = "error: the following required arguments were not provided:\n  --type-list\n  <PATTERN>";
        let out = format!(
            "{}\n\n{}\n\nFor more information, try '--help'.\n",
            header,
            usage_line(prog, &p.flag_seq)
        );
        eprint!("{}", out);
        return Err(2);
    }

    if p.type_list {
        return Ok(Action::TypeList(p));
    }

    Ok(Action::Run(p))
}

fn missing_value_error(prog: &str, name: &str) {
    let (display, possible) = match name {
        "--editor" => ("--editor <EDITOR>", Some(EDITOR_POSSIBLE)),
        "--custom-command" => ("--custom-command <CUSTOM_COMMAND>", None),
        "--theme" => ("--theme <THEME>", Some(THEME_POSSIBLE)),
        "--context-viewer" => ("--context-viewer <CONTEXT_VIEWER>", Some(CONTEXT_VIEWER_POSSIBLE)),
        "--sort" => ("--sort <SORT_BY>", Some(SORT_POSSIBLE)),
        "--sortr" => ("--sortr <SORT_BY_REVERSE>", Some(SORT_POSSIBLE)),
        "--glob" => ("--glob <GLOB>", None),
        "--type" => ("--type <TYPE_MATCHING>", None),
        "--type-not" => ("--type-not <TYPE_NOT>", None),
        _ => (name, None),
    };
    let mut msg = format!("a value is required for '{}' but none was supplied", display);
    if let Some(p) = possible {
        msg.push_str(&format!("\n  [possible values: {}]", p));
    }
    print_clap_error_noflag(prog, &msg);
    let _ = prog;
}

// Error print: no usage line, just error + hint+footer
fn print_clap_error_noflag(_prog: &str, msg: &str) {
    let out = format!("error: {}\n\nFor more information, try '--help'.\n", msg);
    eprint!("{}", out);
}

// Error print with specified flags included in usage line (overriding logic)
fn print_clap_error_fixed_usage(prog: &str, msg: &str, flags: &[&str]) {
    let usage = usage_line(prog, flags);
    let out = format!("error: {}\n\n{}\n\nFor more information, try '--help'.\n", msg, usage);
    eprint!("{}", out);
}

fn validate_custom_command(cmd: &str) -> Result<(), String> {
    // 1. If no space in whole command -> "Expected program and its arguments"
    if !cmd.contains(' ') {
        return Err("Expected program and its arguments".to_string());
    }
    // 2. Parse by simple split on ' ' (not whitespace-collapse), drop first token as program
    let tokens: Vec<&str> = cmd.split(' ').collect();
    // Need at least 2 parts (program + >=1 arg). Since we've passed the space check, len >= 2.
    let args = &tokens[1..];
    let args_joined = args.join(" ");
    let file_count = count_occurrences(&args_joined, "{file_name}");
    if file_count != 1 {
        return Err("Expected one occurrence of '{file_name}'.".to_string());
    }
    let line_count = count_occurrences(&args_joined, "{line_number}");
    if line_count != 1 {
        return Err("Expected one occurrence of '{line_number}'.".to_string());
    }
    Ok(())
}

fn count_occurrences(haystack: &str, needle: &str) -> usize {
    if needle.is_empty() { return 0; }
    let mut count = 0;
    let mut start = 0;
    while let Some(pos) = haystack[start..].find(needle) {
        count += 1;
        start += pos + needle.len();
    }
    count
}

fn run_main() -> ExitCode {
    let argv: Vec<String> = env::args().skip(1).collect();
    let prog = program_name();

    let action = match parse_args(&argv, &prog) {
        Ok(a) => a,
        Err(code) => return ExitCode::from(code as u8),
    };

    match action {
        Action::Help => {
            print_help(&prog);
            ExitCode::from(0)
        }
        Action::Version => {
            print_version();
            ExitCode::from(0)
        }
        Action::TypeList(_) => {
            print_type_list();
            ExitCode::from(0)
        }
        Action::Run(p) => {
            // Validate --custom-command
            if let Some(cc) = p.custom_command.as_deref() {
                if let Err(e) = validate_custom_command(cc) {
                    eprintln!("Error: Incorrect editor command: '{}'", cc);
                    eprintln!();
                    eprintln!("Caused by:");
                    eprintln!("    {}", e);
                    return ExitCode::from(1);
                }
            }

            // Validate -t/-T types against known type list
            if let Some(bad) = p.types_.iter().find(|t| !types::is_known_type(t)) {
                eprintln!("Error: unrecognized file type: {}", bad);
                return ExitCode::from(1);
            }
            if let Some(bad) = p.types_not.iter().find(|t| !types::is_known_type(t)) {
                eprintln!("Error: unrecognized file type: {}", bad);
                return ExitCode::from(1);
            }

            // Validate IGREP_EDITOR env var if set (and no --editor / --custom-command)
            if p.editor.is_none() && p.custom_command.is_none() {
                if let Ok(v) = env::var("IGREP_EDITOR") {
                    if !EDITOR_VALUES.contains(&v.as_str()) {
                        eprintln!("Error: \"{}\" read from $IGREP_EDITOR, possible variants: [{}]", v, EDITOR_POSSIBLE);
                        eprintln!();
                        eprintln!("Caused by:");
                        eprintln!("    invalid variant: {}", v);
                        return ExitCode::from(1);
                    }
                }
                if let Ok(v) = env::var("IGREP_CUSTOM_EDITOR") {
                    if let Err(e) = validate_custom_command(&v) {
                        eprintln!("Error: Incorrect editor command: '{}'", v);
                        eprintln!();
                        eprintln!("Caused by:");
                        eprintln!("    {}", e);
                        return ExitCode::from(1);
                    }
                }
            }

            // Try starting TUI - since we don't implement it, simulate the "no TTY" error
            // which the original binary emits when stdin is not a tty.
            eprintln!("Error: Resource temporarily unavailable (os error 11)");
            ExitCode::from(1)
        }
    }
}

fn main() -> ExitCode {
    run_main()
}
