                        p.push_flag(flag_id);
                    }
                    _ => {
                        let arg_str = format!("-{}", c);
                        let tip = format!("to pass '{}' as a value, use '-- {}'", arg_str, arg_str);
                        let msg = format!("unexpected argument '{}' found", arg_str);
                        print_clap_error(prog, &msg, Some(&tip), &p.flag_seq);
                        return Err(2);
                    }
                }
                j += 1;
            }
            i += 1;
            continue;
        }

        // Positional
        if p.pattern.is_none() {
            p.pattern = Some(arg);
            p.idx_pattern = Some(i);
        } else {
            p.paths.push(arg);
        }
        i += 1;
    }

    // Post-parse validation

    // Check conflict --editor vs --custom-command
    if let (Some(ie), Some(ic)) = (p.idx_editor, p.idx_custom_command) {
        // The one that was specified FIRST (lower index) is X, other is Y.
        // Usage shows X.
        let (x_disp, y_disp, x_flag) = if ie < ic {
            ("--editor <EDITOR>", "--custom-command <CUSTOM_COMMAND>", "editor")
        } else {
            ("--custom-command <CUSTOM_COMMAND>", "--editor <EDITOR>", "custom-command")
        };
        let msg = format!("the argument '{}' cannot be used with '{}'", x_disp, y_disp);
        let mut flags_for_usage: Vec<&str> = Vec::new();
        if p.type_list { flags_for_usage.push("type-list"); }
        flags_for_usage.push(x_flag);
        print_clap_error_fixed_usage(prog, &msg, &flags_for_usage);
        return Err(2);
    }

    // Check --type-list conflicts with <PATTERN>
    if p.type_list && p.pattern.is_some() {
        let it = p.idx_type_list.unwrap_or(usize::MAX);
        let ip = p.idx_pattern.unwrap_or(usize::MAX);
        let (x, y) = if it < ip {
            ("'--type-list'", "'<PATTERN>'")
        } else {
            ("'<PATTERN>'", "'--type-list'")
        };
        let msg = format!("the argument {} cannot be used with {}", x, y);
        // Usage line: always "executable --type-list <PATTERN> [PATHS]..."
        let out = format!(
            "error: {}\n\nUsage: {} --type-list <PATTERN> [PATHS]...\n\nFor more information, try '--help'.\n",
            msg, prog
        );
        eprint!("{}", out);
        return Err(2);
    }

    // Missing required
    if !p.type_list && p.pattern.is_none() {
        let header = "error: the following required arguments were not provided:\n  --type-list\n  <PATTERN>";
        let out = format!(
            "{}\n\n{}\n\nFor more information, try '--help'.\n",
            header,
            usage_line(prog, &p.flag_seq)
        );
        eprint!("{}", out);
        return Err(2);
    }

    if p.type_list {
        return Ok(Action::TypeList(p));
    }

    Ok(Action::Run(p))
}

fn missing_value_error(prog: &str, name: &str) {
    let (display, possible) = match name {
        "--editor" => ("--editor <EDITOR>", Some(EDITOR_POSSIBLE)),
        "--custom-command" => ("--custom-command <CUSTOM_COMMAND>", None),
        "--theme" => ("--theme <THEME>", Some(THEME_POSSIBLE)),
        "--context-viewer" => ("--context-viewer <CONTEXT_VIEWER>", Some(CONTEXT_VIEWER_POSSIBLE)),
        "--sort" => ("--sort <SORT_BY>", Some(SORT_POSSIBLE)),
        "--sortr" => ("--sortr <SORT_BY_REVERSE>", Some(SORT_POSSIBLE)),
        "--glob" => ("--glob <GLOB>", None),
        "--type" => ("--type <TYPE_MATCHING>", None),
        "--type-not" => ("--type-not <TYPE_NOT>", None),
        _ => (name, None),
    };
    let mut msg = format!("a value is required for '{}' but none was supplied", display);
    if let Some(p) = possible {
        msg.push_str(&format!("\n  [possible values: {}]", p));
    }
    print_clap_error_noflag(prog, &msg);
    let _ = prog;
}

// Error print: no usage line, just error + hint+footer
fn print_clap_error_noflag(_prog: &str, msg: &str) {
    let out = format!("error: {}\n\nFor more information, try '--help'.\n", msg);
    eprint!("{}", out);
}

// Error print with specified flags included in usage line (overriding logic)
fn print_clap_error_fixed_usage(prog: &str, msg: &str, flags: &[&str]) {
    let usage = usage_line(prog, flags);
    let out = format!("error: {}\n\n{}\n\nFor more information, try '--help'.\n", msg, usage);
    eprint!("{}", out);
}

fn validate_custom_command(cmd: &str) -> Result<(), String> {
    // 1. If no space in whole command -> "Expected program and its arguments"
    if !cmd.contains(' ') {
        return Err("Expected program and its arguments".to_string());
    }
    // 2. Parse by simple split on ' ' (not whitespace-collapse), drop first token as program
    let tokens: Vec<&str> = cmd.split(' ').collect();
    // Need at least 2 parts (program + >=1 arg). Since we've passed the space check, len >= 2.
    let args = &tokens[1..];
    let args_joined = args.join(" ");
    let file_count = count_occurrences(&args_joined, "{file_name}");
    if file_count != 1 {
        return Err("Expected one occurrence of '{file_name}'.".to_string());
    }
    let line_count = count_occurrences(&args_joined, "{line_number}");
    if line_count != 1 {
        return Err("Expected one occurrence of '{line_number}'.".to_string());
    }
    Ok(())
}

fn count_occurrences(haystack: &str, needle: &str) -> usize {
    if needle.is_empty() { return 0; }
    let mut count = 0;
    let mut start = 0;
    while let Some(pos) = haystack[start..].find(needle) {
        count += 1;
        start += pos + needle.len();
    }
    count
}

fn run_main() -> ExitCode {
    let argv: Vec<String> = env::args().skip(1).collect();
    let prog = program_name();

    let action = match parse_args(&argv, &prog) {
        Ok(a) => a,
        Err(code) => return ExitCode::from(code as u8),
    };

    match action {
        Action::Help => {
            print_help(&prog);
            ExitCode::from(0)
        }
        Action::Version => {
            print_version();
            ExitCode::from(0)
        }
        Action::TypeList(_) => {
            print_type_list();
            ExitCode::from(0)
        }
        Action::Run(p) => {
            // Validate --custom-command
            if let Some(cc) = p.custom_command.as_deref() {
                if let Err(e) = validate_custom_command(cc) {
                    eprintln!("Error: Incorrect editor command: '{}'", cc);
                    eprintln!();
                    eprintln!("Caused by:");
                    eprintln!("    {}", e);
                    return ExitCode::from(1);
                }
            }

            // Validate -t/-T types against known type list
            if let Some(bad) = p.types_.iter().find(|t| !types::is_known_type(t)) {
                eprintln!("Error: unrecognized file type: {}", bad);
                return ExitCode::from(1);
            }
            if let Some(bad) = p.types_not.iter().find(|t| !types::is_known_type(t)) {
                eprintln!("Error: unrecognized file type: {}", bad);
                return ExitCode::from(1);
            }

            // Validate IGREP_EDITOR env var if set (and no --editor / --custom-command)
            if p.editor.is_none() && p.custom_command.is_none() {
                if let Ok(v) = env::var("IGREP_EDITOR") {
                    if !EDITOR_VALUES.contains(&v.as_str()) {
                        eprintln!("Error: \"{}\" read from $IGREP_EDITOR, possible variants: [{}]", v, EDITOR_POSSIBLE);
                        eprintln!();
                        eprintln!("Caused by:");
                        eprintln!("    invalid variant: {}", v);
                        return ExitCode::from(1);
                    }
                }
                if let Ok(v) = env::var("IGREP_CUSTOM_EDITOR") {
                    if let Err(e) = validate_custom_command(&v) {
                        eprintln!("Error: Incorrect editor command: '{}'", v);
                        eprintln!();
                        eprintln!("Caused by:");
                        eprintln!("    {}", e);
                        return ExitCode::from(1);
                    }
                }
            }

            // Try starting TUI - since we don't implement it, simulate the "no TTY" error
            // which the original binary emits when stdin is not a tty.
            eprintln!("Error: Resource temporarily unavailable (os error 11)");
            ExitCode::from(1)
        }
    }
}

fn main() -> ExitCode {
    run_main()
}
